<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,shallowRef,watch} from 'vue';
import {DialogRoot,DialogPortal,DialogOverlay,DialogContent,DialogTitle,DialogDescription,DialogClose} from 'reka-ui';
import type {BulkRecord} from './contracts';
import {projectTarget,badgeClass,label,number} from './bulkDetailPresentation';
import ListCell from '../../components/ListCell.vue';
import FilterPopover from '../../components/FilterPopover.vue';
const props=withDefaults(defineProps<{items:BulkRecord[];selected:Set<string>;loading:boolean;error:string;scope?:string;resultState?:string;resultCounts?:Record<string,number>;resultTotal?:unknown;resultStates?:string[];openTask:(taskId:string,runId?:string|null)=>unknown}>(),{resultState:'',resultCounts:()=>({}),resultStates:()=>[]});
const emit=defineEmits<{toggle:[id:string,checked:boolean];selectPage:[checked:boolean];retry:[];filter:[state:string]}>();
const host=ref<HTMLElement|null>(null),rendered=shallowRef(props.items),projected=computed(()=>rendered.value.map(projectTarget)),selectedCount=computed(()=>projected.value.filter(row=>props.selected.has(row.id)).length);
const filterOpen=ref(false);
const filterStates=computed(()=>[...new Set([...props.resultStates,...(props.resultState?[props.resultState]:[])])]);
function filter(state:string){filterOpen.value=false;emit('filter',state);}
function copying(){const selection=window.getSelection();return Boolean(selection?.toString()&&selection.anchorNode&&host.value?.contains(selection.anchorNode));}
function applyLatest(){if(!copying())rendered.value=props.items;}
watch(()=>props.items,items=>{if(!copying()||!items.length)rendered.value=items;});
watch(()=>props.scope,()=>{rendered.value=props.items;});
onMounted(()=>document.addEventListener('selectionchange',applyLatest));
onBeforeUnmount(()=>document.removeEventListener('selectionchange',applyLatest));
const dialogOpen=ref(false),dialogRow=shallowRef<ReturnType<typeof projectTarget>|null>(null);let trigger:HTMLElement|null=null;
function show(row:ReturnType<typeof projectTarget>,event:Event) {dialogRow.value={...row};trigger=event.currentTarget as HTMLElement;dialogOpen.value=true;}
function restore(event:Event) {event.preventDefault();const target=trigger;trigger=null;if(!target?.isConnected||target.hasAttribute('disabled')||target.closest('[hidden],[inert]'))return;let node:HTMLElement|null=target;while(node){if(getComputedStyle(node).display==='none'||getComputedStyle(node).visibility==='hidden')return;node=node.parentElement;}target.focus({preventScroll:true});}
function close() {dialogOpen.value=false;filterOpen.value=false;}
function checked(event:Event){return (event.target as HTMLInputElement).checked;}
function task(id:string,run:string|null=null){void props.openTask(id,run);}
defineExpose({close});
</script>
<template>
  <div ref="host" class="bulk-targets" :aria-busy="loading">
    <div v-if="error" class="bulk-error" role="alert">{{error}} <button type="button" class="bulk-link" @click="emit('retry')">重试读取明细</button></div>
    <div class="bulk-target-scroll" role="region" aria-label="账号明细内容" tabindex="0"><table class="bulk-table bulk-target-table"><thead><tr><th><input type="checkbox" data-select-page aria-label="选择当前页目标" :disabled="!projected.length" :checked="projected.length>0&&selectedCount===projected.length" :indeterminate="selectedCount>0&&selectedCount<projected.length" @change="emit('selectPage',checked($event))"></th><th>ID</th><th>账号</th><th><FilterPopover v-if="resultStates.length" label="结果状态" trigger-label="结果 / 阶段" :active="!!resultState" :summary="label(resultState)" :open="filterOpen" @update:open="filterOpen=$event"><fieldset class="bulk-target-filter"><legend class="bulk-sr-only">结果状态</legend><label><input type="radio" name="bulk-target-state" value="" :checked="!resultState" @change="filter('')"><span>全部</span><strong>{{number(resultTotal)}}</strong></label><label v-for="value in filterStates" :key="value"><input type="radio" name="bulk-target-state" :value="value" :checked="resultState===value" @change="filter(value)"><span>{{label(value)}}</span><strong>{{resultCounts[value]||0}}</strong></label></fieldset></FilterPopover><template v-else>结果 / 阶段</template></th><th>结果摘要</th><th>错误分类</th><th>操作</th></tr></thead>
      <tbody><tr v-for="row in projected" :key="row.id" :data-bulk-row-target="row.id"><td class="bulk-target-check" data-label="选择"><input type="checkbox" :data-bulk-target="row.id" :aria-label="'选择账号 '+row.account" :checked="selected.has(row.id)" @change="emit('toggle',row.id,checked($event))"></td><td class="bulk-target-id" data-label="ID"><button type="button" class="bulk-cell-detail" :aria-label="'查看完整账号 ID：'+row.accountId" @click="show(row,$event)">#{{row.accountId}}</button></td><td class="bulk-target-account" data-label="账号"><button type="button" class="bulk-cell-detail" :title="row.account" @click="show(row,$event)">{{row.account}}</button></td><td class="bulk-target-state" data-label="结果 / 阶段"><div class="bulk-target-status-line"><span class="bulk-badge" :class="badgeClass(row.stateKey)">{{row.state}}</span><button v-if="row.stage && !['—','-'].includes(row.stage)" type="button" class="bulk-cell-detail bulk-target-stage" @click="show(row,$event)">{{row.stage}}</button></div></td><td class="bulk-target-summary" data-label="结果摘要"><ListCell :text="row.summaryShort" :title="row.summary"><button type="button" class="bulk-cell-detail" data-result-detail :title="row.summary" :aria-label="'查看完整结果摘要：'+row.summary" @click="show(row,$event)">{{row.summaryShort}}</button></ListCell></td><td class="bulk-target-reason" data-label="错误分类"><ListCell v-if="row.reason" :text="row.reasonShort" :title="row.reason"><button type="button" class="bulk-cell-detail" :title="row.reason" @click="show(row,$event)">{{row.reasonShort}}</button></ListCell><template v-else>—</template></td><td class="bulk-target-actions" data-label="操作"><div class="bulk-target-action-line"><button v-if="row.taskId" type="button" class="jobs-tb-btn" data-owned-task @click="task(row.taskId,row.runId)">查看执行</button><span v-else>尚未创建执行</span><button v-if="row.blockerTaskId" type="button" class="bulk-link" data-blocker-task title="查看占用任务（其他执行）" @click="task(row.blockerTaskId)">查看占用</button></div></td></tr>
      <tr v-if="!projected.length"><td colspan="7"><div class="bulk-empty" role="status">{{loading?'正在读取账号明细…':'当前条件下没有目标。更改结果筛选不会改变本批固定名单。'}}</div></td></tr>
    </tbody></table></div>
  </div>
  <DialogRoot v-model:open="dialogOpen"><DialogPortal><DialogOverlay class="bulk-vue-overlay"/><DialogContent class="bulk-vue-dialog" @close-auto-focus="restore"><DialogTitle>账号执行详情</DialogTitle><DialogDescription>{{dialogRow?.account}} · 账号 #{{dialogRow?.accountId}}</DialogDescription><dl v-if="dialogRow" class="bulk-vue-result-details"><dt>结果 / 阶段</dt><dd>{{dialogRow.state}} · {{dialogRow.stage||'—'}}</dd><dt>结果摘要</dt><dd>{{dialogRow.summary}}</dd><template v-if="dialogRow.capabilities"><dt>能力结果</dt><dd>{{dialogRow.capabilities}}</dd></template><dt>错误分类 / 错误码</dt><dd>{{dialogRow.reasonContent||'—'}}</dd><dt>所属执行</dt><dd>{{dialogRow.taskId?'任务 #'+dialogRow.taskId:'尚未创建执行'}}{{dialogRow.runId?' · 运行 #'+dialogRow.runId:''}}</dd><template v-if="dialogRow.blockerTaskId"><dt>占用任务（其他执行）</dt><dd>#{{dialogRow.blockerTaskId}}</dd></template></dl><DialogClose class="jobs-tb-btn" data-close-detail>关闭</DialogClose></DialogContent></DialogPortal></DialogRoot>
</template>
<style>
.bulk-targets{min-width:0}.bulk-target-scroll{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain}.bulk-target-scroll:focus-visible{outline:2px solid var(--ui-color-brand);outline-offset:2px}.bulk-target-table td{vertical-align:middle}
.bulk-target-filter{display:grid;gap:3px;margin:0;padding:0;border:0}.bulk-target-filter label{display:flex;align-items:center;gap:8px;min-height:32px;cursor:pointer}.bulk-target-filter input{width:16px;min-width:16px;height:16px;min-height:16px;padding:0;margin:0;flex:0 0 auto;accent-color:var(--ui-color-brand)}.bulk-target-filter strong{margin-left:auto;font-size:12px;font-variant-numeric:tabular-nums;color:var(--ui-color-text-secondary)}@media(max-width:680px){.bulk-target-filter label{min-height:40px}}
.bulk-vue-overlay{position:fixed;inset:0;background:#0008;z-index:1200}.bulk-vue-dialog{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:1201;width:min(640px,calc(100vw - 32px));max-height:calc(100dvh - 48px);overflow:auto;padding:24px;border:1px solid var(--ui-color-border);border-radius:12px;background:var(--ui-color-surface,#fff);color:var(--ui-color-text,#182230);box-sizing:border-box}.bulk-vue-dialog h2{font-size:18px;margin:0 0 10px}.bulk-vue-dialog p{color:var(--ui-color-text-secondary);line-height:1.6}.bulk-vue-result-details{display:grid;gap:8px;overflow-wrap:anywhere}.bulk-vue-result-details dt{font-size:12px;color:var(--ui-color-text-secondary)}.bulk-vue-result-details dd{margin:0 0 10px;white-space:pre-wrap;font-size:13px;line-height:1.6}.bulk-vue-dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}
</style>
